function groupSum(rows){
  const out = new Map();
  for (const r of rows){
    const key = String(r.u);
    const cur = out.get(key) || { u: r.u, s: r.s, total: 0 };
    cur.total += r.t;
    out.set(key, cur);
  }
  return [...out.values()];
}

